  function showMenu(){
    if(activeWorldId&&!inMenu)save();closeModal();inMenu=true;activeWorldId=null;paused=false;flight=null;replay=false;history=[];keys.clear();overviewRenderer=null;taskFeedback=null;accumulator=0;
    if(gain)gain.gain.value=0;$('app').classList.add('hidden');$('flight-screen').classList.add('hidden');$('main-menu').classList.remove('hidden');document.body.classList.add('at-main-menu');$('toast').classList.add('hidden');menuSearch='';renderMenu();window.scrollTo(0,0);
  }
  function worldPreview(canvas,state,mode=4){const renderer=new SkyWorld.Renderer(canvas),preview=JSON.parse(JSON.stringify(state));preview.settings.graphics='low';renderer.render(preview,null,mode,0);}
  function loadWorld(id,created=false){
    if(activeWorldId&&!inMenu)save();const record=worlds.read().worlds.find(w=>w.id===id);if(!record){toast('This airport is no longer in the library.');if(inMenu)renderMenu();return;}
    state=C.sanitize(record.state);activeWorldId=id;inMenu=false;paused=false;flight=null;replay=false;history=[];taskFeedback=null;keys.clear();accumulator=0;saveTime=0;menuRenderer=null;
    closeModal();$('main-menu').classList.add('hidden');$('flight-screen').classList.add('hidden');$('app').classList.remove('hidden');document.body.classList.remove('at-main-menu');save();go(created&&tutorial()?'tutorial':'overview');
    if(!worlds.available)toast(worlds.warning);
  }
  function createWorldDialog(){
    modal('A new world. All yours.',`<p class="creation-intro">Give your airport a name, then decide how you want to play.</p><form id="create-world-form"><label class="creation-label" for="new-world-name">WORLD NAME <span>YOU CAN RENAME IT LATER</span></label><input id="new-world-name" class="creation-name" name="name" type="text" maxlength="40" required placeholder="e.g. Cloud Nine International" autocomplete="off"><fieldset class="creation-mode"><legend>YOUR WAY TO PLAY <span>CHOSEN ONCE</span></legend><div class="creation-mode-options four"><label class="mode-choice"><input type="radio" name="world-mode" value="business" checked><span class="mode-choice-icon">${icon('build')}</span><strong>Build an empire</strong><small>${C.MODES.business.description}</small><span class="mode-choice-caption">BUSINESS MODE</span></label><label class="mode-choice"><input type="radio" name="world-mode" value="flight"><span class="mode-choice-icon">${icon('plane')}</span><strong>Just take flight</strong><small>${C.MODES.flight.description}</small><span class="mode-choice-caption">FLIGHT ONLY</span></label><label class="mode-choice"><input type="radio" name="world-mode" value="competitive"><span class="mode-choice-icon">${icon('chart')}</span><strong>Race the clock</strong><small>${C.MODES.competitive.description} No missions, no business.</small><span class="mode-choice-caption">COMPETITIVE MODE</span></label><label class="mode-choice"><input type="radio" name="world-mode" value="free"><span class="mode-choice-icon">${icon('sun')}</span><strong>Just fly</strong><small>${C.MODES.free.description} Land anywhere to refuel.</small><span class="mode-choice-caption">FREE FLIGHT</span></label></div></fieldset><fieldset class="creation-mode"><legend>WORLD TYPE <span id="world-type-note">20 MAPS · CHOSEN ONCE</span></legend><div class="terrain-tabs" role="tablist">${Object.entries(C.TERRAINS).map(([k,t],i)=>`<button type="button" class="terrain-tab ${i?'':'active'}" role="tab" aria-selected="${!i}" data-action="terrain-tab" data-id="${k}">${t.short}<small>${C.mapsFor(k).length} maps</small></button>`).join('')}</div>${Object.keys(C.TERRAINS).map((k,i)=>`<div class="terrain-choices ${i?'hidden':''}" data-terrain-panel="${k}">${C.mapsFor(k).map((m,j)=>`<label class="terrain-choice"><input type="radio" name="world-map" value="${m.id}" ${!i&&!j?'checked':''}><canvas class="terrain-preview" data-map-preview="${m.id}" aria-hidden="true"></canvas><strong>${m.name}</strong><small>${m.description}</small><span class="terrain-race">${SHAPE_NAMES[m.race.shape].toUpperCase()} · ${m.course.gates} GATES</span></label>`).join('')}</div>`).join('')}</fieldset><label class="tutorial-choice" for="new-world-tutorial"><span class="tutorial-choice-icon">${icon('book')}</span><span><strong>A little guidance?</strong><small>Start at flight school with a guided training mission and helpful flying tips.</small></span><input id="new-world-tutorial" name="tutorial" type="checkbox" checked><span class="switch-track" aria-hidden="true"></span></label><p class="creation-lock">${icon('shield')} Play mode, world type, and tutorial are locked when you create this world. You can always create another.</p><div class="button-row creation-buttons"><button type="submit" class="btn primary">Create & enter world ${arrow()}</button><button type="button" class="btn" data-action="close-modal">Not yet</button></div></form>`);
    requestAnimationFrame(()=>{$('new-world-name')?.focus();renderMapPreviews('island');});
  }
  function renderMapPreviews(terrain){
    document.querySelectorAll(`[data-terrain-panel="${terrain}"] [data-map-preview]`).forEach(canvas=>{if(canvas.dataset.rendered)return;canvas.dataset.rendered='1';const preview=C.freshState({business:false,map:canvas.dataset.mapPreview});preview.settings.weather='clear';worldPreview(canvas,preview,5);});
  }
  function showTerrainTab(terrain){
    document.querySelectorAll('.terrain-tab').forEach(b=>{const on=b.dataset.id===terrain;b.classList.toggle('active',on);b.setAttribute('aria-selected',on);});
    document.querySelectorAll('[data-terrain-panel]').forEach(p=>p.classList.toggle('hidden',p.dataset.terrainPanel!==terrain));
    const first=document.querySelector(`[data-terrain-panel="${terrain}"] input[name="world-map"]`);if(first&&!document.querySelector(`[data-terrain-panel="${terrain}"] input[name="world-map"]:checked`))first.checked=true;
    renderMapPreviews(terrain);
  }
  function worldSettingsDialog(id){const w=worlds.read().worlds.find(w=>w.id===id);if(!w)return;const wm=w.state.world.mode||(w.state.world.business?'business':'flight');modal('World settings',`<form id="menu-world-rename" data-id="${id}"><label class="creation-label" for="edit-world-name">WORLD NAME</label><input id="edit-world-name" class="creation-name" type="text" required maxlength="40" value="${escape(w.state.world.name)}"><div class="locked-options"><div>${icon(wm==='business'?'build':wm==='competitive'?'chart':wm==='free'?'sun':'plane')}<span><strong>${C.MODES[wm].name}</strong><small>Play mode · chosen at creation</small></span><span class="locked-label">LOCKED</span></div><div>${icon('grid')}<span><strong>${escape(mapDef(w.state.world).name)}</strong><small>${C.TERRAINS[mapDef(w.state.world).terrain].short} world · chosen at creation</small></span><span class="locked-label">LOCKED</span></div><div>${icon('book')}<span><strong>Tutorial ${w.state.world.tutorial?'enabled':'disabled'}</strong><small>Selected when this world was created</small></span><span class="locked-label">LOCKED</span></div></div><p class="help-note">These play-style choices stay with this world. Difficulty, graphics, and weather can be changed inside the world.</p><div class="button-row"><button class="btn primary" type="submit">Save name</button><button class="btn" type="button" data-action="export-world" data-id="${id}">Export world</button><button class="btn danger" type="button" data-action="delete-world" data-id="${id}">Delete world</button></div></form>`);}
