  function taskFor(role){const tasks=TASKS[role];return tasks[(state.taskSequence+Object.keys(TASKS).indexOf(role))%tasks.length];}
  function rolePage(){
    const r=C.ROLES[state.role];
    if(state.role==='manager')return overview();
    if(state.role==='pilot')return operations();
    const t=taskFor(state.role),cool=state.seconds<state.taskReadyAt;
    return heading('EVERY ROLE MAKES A DIFFERENCE','A good day starts with you.','Work a shift, help your team, and keep Seabreeze moving.',`<button class="btn" data-action="roles">Change role ${arrow()}</button>`)+
    `<div class="shift-header"><span class="staff-portrait">${r.initial}</span><div><h2>${r.name}</h2><p>${r.description}<br>Correct task: +$120 · +0.5 reputation ${C.STAFF[state.role].stage!==undefined?'· advances a matching flight':''}</p></div></div>
    <section class="workstation">${taskFeedback?`<span class="badge ${taskFeedback.correct?'':'amber'}">${taskFeedback.correct?'Nicely handled':'Let’s learn from that'}</span><h3 style="margin-top:20px">${taskFeedback.correct?'Another little win for your airport.':'Here’s what to do next time.'}</h3><p>${taskFeedback.explain}</p><p>${taskFeedback.correct?'$120 has been added to your airport funds.':'No money lost. Reputation decreased by 1 point.'}</p><button id="cooldown-label" class="btn primary" data-action="next-task" ${cool?'disabled':''}>${cool?`Next task in ${Math.ceil(state.taskReadyAt-state.seconds)}s`:'Next passenger / aircraft'}</button>`:cool?`<h3>A moment between jobs.</h3><p>Your next task will be ready shortly. Your employees are still working.</p><button id="cooldown-label" class="btn primary" data-action="next-task" disabled>Next task in ${Math.ceil(state.taskReadyAt-state.seconds)}s</button>`:`<p class="eyebrow">SHIFT TASK / ${String(state.taskSequence+1).padStart(3,'0')}</p><h3>${t.title}</h3><p>${t.text}</p><div class="document">${t.fields.map(([a,b])=>`<div><small>${a}</small><strong>${b}</strong></div>`).join('')}</div><div class="task-choices">${t.choices.map((a,i)=>`<button class="btn" data-action="answer" data-id="${i}"><span class="tag">0${i+1}</span>${a}</button>`).join('')}</div>`}</section><p class="help-note">Tasks are fictional learning scenarios with their own stated rules. Your automated team keeps working while you play.</p>`;
  }
  function roleModal(){if(!business())return;modal('One airport. Your choice.',`<p>Manage the big picture or get hands-on. Your employees continue their jobs while you switch roles.</p><div class="role-grid">${Object.entries(C.ROLES).map(([k,r])=>`<button class="role-option ${state.role===k?'selected':''}" data-action="role" data-id="${k}"><span class="role-avatar">${r.initial}</span><span><strong>${r.name}</strong><small>${r.description}</small></span></button>`).join('')}</div>`);}
  function courseModal(){modal('Make your own air rally.',`<p>Design a single-player circuit around the island. The route starts with a takeoff gate and ends with an approach to runway 36. Wider circuits allow gentler turns.</p><div class="route-editor"><label>Number of course gates<input id="course-gates" type="number" min="4" max="12" value="${state.course.gates}"></label><label>Circuit radius (metres)<input id="course-radius" type="number" min="700" max="1600" step="50" value="${state.course.radius}"></label><label>Cruise altitude (metres)<input id="course-altitude" type="number" min="120" max="420" step="10" value="${state.course.altitude}"></label><label>Direction<select id="course-direction"><option value="left" ${state.course.direction==='left'?'selected':''}>Left circuit</option><option value="right" ${state.course.direction==='right'?'selected':''}>Right circuit</option></select></label></div><p class="help-note">The return route adds one downwind gate and two landing-approach gates. Your design is included in exported save files. Changing the course resets its best time and ghost aircraft.</p>`,`<button class="btn primary" data-action="save-course">Save circuit ${arrow()}</button><button class="btn" data-action="close-modal">Cancel</button>`);}
  function briefing(type){
    const m=C.MISSIONS[type];if(!m||!tutorial()&&type==='training')return;
    const reward=m.reward*(1+state.buildings.runway*.1)*(type==='emergency'?1+state.buildings.rescue*.2:1);
    if(competitive()&&type!=='race')return;if(free())return;
    pendingDestination=isDestination(type)?C.pickDestination(state,type):null;if(isDestination(type)&&!pendingDestination)return;
    const dest=pendingDestination&&C.MAPS.find(x=>x.id===pendingDestination.map);
    modal(competitive()?'Ready to race?':m.title,`<p class="eyebrow">${competitive()?'TIME TRIAL':m.category} / ${m.aircraft.toUpperCase()}</p><p>${competitive()?`Fly every gate in order, then land on runway 36 and brake to a stop. The timer starts immediately. ${state.raceRecord?'Your ghost flies your record lap beside you.':'Finish to set your first record and unlock the ghost aircraft.'}`:m.description}</p><div class="stats-grid">${competitive()?stat('Your record',state.bestRace?formatRace(state.bestRace):'—',state.raceRecord?'Ghost aircraft ready':'No ghost yet','chart'):business()?stat('Mission pay',money(reward),'Safe landing required','wallet'):stat('Your flight',m.duration,'No budget or business costs','plane')}${stat('Conditions',({clear:'Clear',overcast:'Overcast',storm:'Storm',sunset:'Sunset'})[state.settings.weather],({easy:'Relaxed',normal:'Standard',hard:'Challenging'})[state.settings.difficulty]+' · simulation physics','sun')}</div>${tutorial()?'<p><strong>Before you go:</strong> F for takeoff flaps. Hold + / Shift for full throttle. At 65–70 knots, gently pull the nose up with S / ↓. Follow the numbered gates, then land on runway 36 and brake to a stop.</p>':''}${type==='emergency'?'<p><strong>Emergency exercise:</strong> engine power will drop soon after take-off. Use full available power and keep your airspeed up.</p>':''}${type==='race'&&state.bestRace&&!competitive()?'<p>Your best circuit: <strong>'+formatRace(state.bestRace)+'</strong>'+'</p>':''}${dest?`<div class="destination-card">${icon('arrow')}<span><strong>Destination: ${escape(dest.name)}</strong><small>${C.TERRAINS[dest.terrain].name} · ${km(pendingDestination.dx,pendingDestination.dz)} to the ${bearingName(pendingDestination.dx,pendingDestination.dz)} · land on its runway ${destRunwayName(type,pendingDestination.map)}${mode()==='flight'?(type==='return'?' · you will be back home':' · your next flight starts there'):' · your next flight starts back home'}</small></span></div>`:''}<p class="help-note">${business()?'Your employees keep working. Mission rewards go into this world’s airport budget.':competitive()?'Only a completed race can set a record. Crashes and early exits are never counted.':'Your mission results and race records stay with this world. Just enjoy the flight.'} Flights in progress restart from the runway if you close the browser.</p>`, `<button class="btn primary" data-action="launch" data-id="${type}">${competitive()?'Start the clock':'Ready for takeoff'} ${icon('plane')}</button>${tutorial()?'<button class="btn" data-action="brief-tutorial">Read the tutorial first</button>':''}`);
  }
  function formatDuration(t){return `${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`;}
  function formatRace(t){return `${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}.${Math.floor(t*10%10)}`;}
  function formatDelta(d){return (d<0?'−':'+')+Math.abs(d).toFixed(1)+'s';}
