  function audioTick(){if(!gain)return;const active=flight&&!isPaused()&&!flight.crashed&&!flight.completed&&state.settings.sound;gain.gain.setTargetAtTime(active?.012+flight.throttle*.013:0,audio.currentTime,.12);if(active)engine.frequency.setTargetAtTime(30+flight.throttle*85,audio.currentTime,.12);}
