  $('map-zoom-centre').onclick=recentreMap;
  $('map-zoom-in').onclick=()=>zoomMap(1);$('map-zoom-out').onclick=()=>zoomMap(-1);$('map-zoom-size').onclick=toggleMapSize;
  function nearestIsland(f){let best=null;for(const isle of flight.islands){const d=Math.hypot(isle.x-f.x,isle.z-f.z);if(!best||d<best.d)best={isle,d};}return best;}
