    if(e.type==='crash'&&!completionShown){completionShown=true;const terrainHit=/terrain/.test(e.reason);modal(terrainHit?'The scenery is solid.':'A fresh start is always possible.',`<p>${escape(e.reason)}</p><p>${terrainHit?'Mountains, hills, and mesas can be flown around or over. Gates are always placed clear of them, so follow the ring and give the high ground a wide berth.':'Try a gentler approach: gear down, wings level, 65–80 knots, and a slow descent.'} There is no repair charge or loss of airport progress.</p><p class="help-note">${terrainHit?'Tip: the navigation map shows the land; the edge arrow always points to the next gate.':'Tip: read Flight school’s landing lesson before your next attempt.'}</p>`,`<button class="btn primary" data-action="retry">Try this flight again ${arrow()}</button><button class="btn" data-action="end-flight">Back to the airport</button><button class="btn" data-action="replay">Watch replay</button>`);}
    if(e.type==='complete'&&!completionShown&&flight.type==='race'){completionShown=true;const previous=state.bestRace;C.rewardFlight(state,flight,competitive()?raceTrace:undefined);save();const record=flight.newRecord;
      modal(record?(previous?'New record!':'Your first record is on the board.'):'Race finished.',`<p class="eyebrow">${competitive()?'TIME TRIAL':'AIR RACING'} / ${C.MISSIONS.race.aircraft.toUpperCase()}</p><p>${record?(previous?`You beat your previous best of <strong>${formatRace(previous)}</strong>.${competitive()?' Your ghost aircraft now flies this lap.':''}`:competitive()?'Your ghost aircraft will fly this lap beside you next time. Beat it to set a new record.':'Your first record for this circuit is in the logbook.'):`Your record of <strong>${formatRace(state.bestRace)}</strong> stands. ${formatDelta(flight.time-state.bestRace)} behind — try a tighter line through the gates.`}</p><div class="stats-grid">${stat('Your time',formatRace(flight.time),record?'New record':'This attempt','chart')}${stat('Record',formatRace(state.bestRace),record?'Set just now':'Still the one to beat','shield')}</div>`,`<button class="btn primary" data-action="retry">Race again ${arrow()}</button><button class="btn" data-action="end-flight">${competitive()?'Back to the track':'Back to the airport'}</button><button class="btn" data-action="replay">Watch replay</button>`);}
    if(e.type==='complete'&&!completionShown&&flight.destination){completionShown=true;const reward=C.rewardFlight(state,flight);const dest=flight.islands[1].map,home=flight.type==='return';save();
      modal(home?'Welcome home.':`Welcome to ${escape(dest.name)}.`,`<p class="eyebrow">MISSION COMPLETE / ${C.MISSIONS[flight.type].category}</p><p>${home?'You crossed the water and brought the aircraft back to your own runway.':`You crossed the water and landed safely on ${escape(dest.name)}.`} ${business()?'Your airport grows a little stronger.':mode()==='flight'&&!home?`Your next flight starts here on ${escape(dest.name)}; choose <strong>Homeward bound</strong> whenever you want to fly back.`:'Another crossing for your logbook.'}</p><div class="stats-grid">${business()?stat('Added to your budget',money(reward),'Mission funds received','wallet'):stat('Flights completed',state.missions,'Saved in this world','plane')}${stat('Flight time',formatDuration(flight.time),flight.type==='cargo'?Math.round(flight.cargo)+'% cargo condition':'Safe touchdown. Good work.','plane')}</div>${business()?'<p class="help-note">Your next flight starts back at your own airport.</p>':''}`,`<button class="btn primary" data-action="end-flight">${business()?'Back to your airport':home?'Back to your island':'Explore '+escape(dest.name)} ${arrow()}</button><button class="btn" data-action="replay">Watch flight replay</button>`);}
    if(e.type==='complete'&&!completionShown){completionShown=true;const reward=C.rewardFlight(state,flight);save();modal('That’s a beautiful arrival.',`<p class="eyebrow">MISSION COMPLETE / ${C.MISSIONS[flight.type].category}</p><p>${business()?'You followed the route, brought the aircraft home, and helped your airport grow.':'You followed the route and brought the aircraft safely home. Another flight for your logbook.'}</p><div class="stats-grid">${business()?stat('Added to your budget',money(reward),'Mission funds received','wallet'):stat('Missions completed',state.missions,'Saved in this world','plane')}${stat('Flight time',formatDuration(flight.time),flight.type==='cargo'?Math.round(flight.cargo)+'% cargo condition':'Safe touchdown. Good work.','plane')}</div>`, `<button class="btn primary" data-action="end-flight">${business()?'Back to your airport':'Choose another flight'} ${arrow()}</button><button class="btn" data-action="replay">Watch flight replay</button>`);}
